//! Built-in blocklist presets (data) and domain normalization helpers.

use std::net::IpAddr;

pub struct Preset {
    pub key: &'static str,
    pub name: &'static str,
    /// Registrable domains; subdomains are generated by [`Preset::expanded_domains`].
    pub domains: &'static [&'static str],
    /// Extra fully-qualified hostnames that don't follow the common prefix pattern.
    pub extra_hosts: &'static [&'static str],
    pub processes: &'static [&'static str],
    pub steam_games: bool,
}

/// Prefixes added to every preset domain (hosts files have no wildcards).
pub const COMMON_PREFIXES: &[&str] = &["www", "m", "mobile", "old", "web", "app", "new"];

impl Preset {
    pub fn expanded_domains(&self) -> Vec<String> {
        let mut out = Vec::new();
        for d in self.domains {
            out.push((*d).to_string());
            for p in COMMON_PREFIXES {
                out.push(format!("{p}.{d}"));
            }
        }
        for h in self.extra_hosts {
            out.push((*h).to_string());
        }
        out.sort();
        out.dedup();
        out
    }
}

pub fn presets() -> &'static [Preset] {
    &PRESETS
}

pub fn preset(key: &str) -> Option<&'static Preset> {
    PRESETS.iter().find(|p| p.key == key)
}

