/// Normalize user input into a bare lowercase hostname.
/// Accepts URLs ("https://www.Example.com/path"), strips ports/paths/leading dots.
/// Rejects IP addresses (blocking is domain-based only), wildcards and junk.
pub fn normalize_domain(input: &str) -> Option<String> {
    let mut s = input.trim().to_lowercase();
    if let Some(i) = s.find("://") {
        s = s[i + 3..].to_string();
    }
    if let Some(i) = s.find(['/', '?', '#']) {
        s.truncate(i);
    }
    if let Some(i) = s.rfind('@') {
        s = s[i + 1..].to_string();
    }
    if s.starts_with('[') {
        return None; // IPv6 literal
    }
    if let Some(i) = s.rfind(':') {
        s.truncate(i);
    }
    let s = s.trim_matches('.').to_string();
    if s.is_empty() || s.len() > 253 || s.parse::<IpAddr>().is_ok() {
        return None;
    }
    if !s.contains('.') {
        return None;
    }
    let ok_label = |l: &str| {
        !l.is_empty()
            && l.len() <= 63
            && !l.starts_with('-')
            && !l.ends_with('-')
            && l.chars().all(|c| c.is_ascii_alphanumeric() || c == '-')
    };
    if !s.split('.').all(ok_label) {
        return None;
    }
    // All-numeric last label => looks like an IPv4-ish thing.
    if s.rsplit('.').next().is_some_and(|l| l.chars().all(|c| c.is_ascii_digit())) {
        return None;
    }
    Some(s)
}

/// Normalize a list, dropping invalid entries and duplicates (order kept).
pub fn normalize_domains<I: IntoIterator<Item = S>, S: AsRef<str>>(items: I) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    for i in items {
        if let Some(d) = normalize_domain(i.as_ref()) {
            if !out.contains(&d) {
                out.push(d);
            }
        }
    }
    out
}

/// Normalize a process name: lowercase, trim, strip a trailing ".exe".
pub fn normalize_process(name: &str) -> String {
    let n = name.trim().to_lowercase();
    n.strip_suffix(".exe").map(str::to_string).unwrap_or(n)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn expands_subdomains() {
        let p = preset("social").unwrap();
        let d = p.expanded_domains();
        assert!(d.contains(&"reddit.com".to_string()));
        assert!(d.contains(&"www.reddit.com".to_string()));
        assert!(d.contains(&"m.reddit.com".to_string()));
        let mut s = d.clone();
        s.dedup();
        assert_eq!(s.len(), d.len());
    }

    #[test]
    fn all_preset_domains_valid() {
        for p in presets() {
            for d in p.expanded_domains() {
                assert_eq!(normalize_domain(&d).as_deref(), Some(d.as_str()), "{d}");
            }
        }
    }

    #[test]
    fn normalizes() {
        assert_eq!(normalize_domain("https://WWW.Example.com:8080/a?b").as_deref(), Some("www.example.com"));
        assert_eq!(normalize_domain(".example.org.").as_deref(), Some("example.org"));
        assert_eq!(normalize_domain("1.2.3.4"), None);
        assert_eq!(normalize_domain("[::1]"), None);
        assert_eq!(normalize_domain("::1"), None);
        assert_eq!(normalize_domain("localhost"), None);
        assert_eq!(normalize_domain("*.example.com"), None);
        assert_eq!(normalize_domain("exa mple.com"), None);
        assert_eq!(normalize_domain("evil.com\n0.0.0.0 bank.com"), None);
        assert_eq!(normalize_domain("example.123"), None);
    }

    #[test]
    fn process_names() {
        assert_eq!(normalize_process(" Discord.EXE "), "discord");
    }
}
